        msg = 'You have the prepared ' + target + '. Go to the ' + dest + ' and use the put action there; do not put it on or in a different receptacle.'
    elif stage == 'find_target' and 'two' in (ctx.get('task.task_type') or ''):
        msg = 'One ' + target + ' is already placed. Leave it there, find another ' + target + ', and return to the same ' + dest + '.'
    if not msg:
        return None
    key = stage + ':' + msg[:70]
    if nb.get('last_hint') == key:
        return None
    nb['last_hint'] = key
    return {'message': msg}

def getv(ctx, path, default=None):
    if isinstance(ctx, dict) and path in ctx:
        return ctx.get(path, default)
    cur = ctx
    for part in path.split('.'):
        if isinstance(cur, dict) and part in cur:
            cur = cur.get(part)
        else:
            return default
    return cur

def text(x):
    if x is None:
        return ''
    if isinstance(x, dict):
        return ' '.join([text(v) for v in x.values()]).lower()
    if isinstance(x, list) or isinstance(x, tuple):
        return ' '.join([text(v) for v in x]).lower()
    return str(x).lower()

def hook(ctx, nb):
    action = text(getv(ctx, 'action.final_action', getv(ctx, 'action.normalized', getv(ctx, 'action.raw', ''))))
    target = nb.get('target_type') or text(getv(ctx, 'task.target_type', ''))
    dest = nb.get('destination_type') or text(getv(ctx, 'task.destination_type', ''))
    trans = nb.get('transform') or ''
    task_type = text(getv(ctx, 'task.task_type', ''))
    if not target or not action:
        return None
    pc = nb.get('placed_count', 0)
    try:
        pc = int(pc)
    except Exception:
        pc = 0
    locs = nb.get('placed_locs') or []
    if not isinstance(locs, (list, tuple)):
        locs = []
    placed_here = pc > 0 and dest and (' from ' + dest) in action
    if placed_here or (pc > 0 and target in action and ' from ' in action and any(target in text(x) for x in locs)):
        return {'kind': 'block_and_prompt', 'message': 'Do not take back a target that has already been placed. Leave it there and continue with any remaining required target or final step.'}
    if nb.get('has_target') and trans and not nb.get('transformed') and trans != 'clean' and trans != 'heat' and trans != 'cool':
        if action.startswith('put ' + target + ' '):
            return {'kind': 'block_and_prompt', 'message': 'Do not place the target yet. First complete the required ' + trans + ' step using the admissible transform action.'}
        if trans == 'clean' and 'wash' in task_type and action.startswith('wash ' + target + ' '):
            return {'kind': 'block_and_prompt', 'message': 'Do not wash the target here. Use the admissible clean action at the proper appliance or sink first.'}
        if trans != 'clean' and action.startswith(trans + ' ' + target + ' '):
            return {'kind': 'block_and_prompt', 'message': 'Do not use the wrong transform action. Use the admissible ' + trans + ' action for this target.'}
    wrong_put = bool(dest and action.startswith('put ' + target + ' ') and dest not in action and nb.get('has_target'))
    if wrong_put and (action in (ctx.get('output') or '') or 'nothing happens' in (ctx.get('observation') or '') or 'not enough' in (ctx.get('observation') or '')):
        return {'kind': 'block_and_prompt', 'message': 'This is not the required destination for the target. Carry it to the ' + dest + ' and put it there.'}
    return None
